#include <coroutine>
#include <cstddef>
#include <cstdint>
#include <exception>
#include <iostream>
#include <new>

class Traced {
public:
    struct promise_type {  // every hook the compiler calls, in the order it calls them
        std::int64_t result = 0;
        static void* operator new(std::size_t size) {  // the frame: promise, parameters, locals
            std::cout << "  operator new: the frame\n";
            return ::operator new(size);
        }
        static void operator delete(void* frame) {
            std::cout << "  operator delete: the frame\n";
            ::operator delete(frame);
        }
        promise_type() { std::cout << "  promise constructed\n"; }
        Traced get_return_object() {
            std::cout << "  get_return_object\n";
            return Traced{std::coroutine_handle<promise_type>::from_promise(*this)};
        }
        std::suspend_always initial_suspend() noexcept {
            std::cout << "  initial_suspend\n";
            return {};
        }
        void return_value(std::int64_t v) {  // what co_return v calls
            std::cout << "  return_value(" << v << ")\n";
            result = v;
        }
        std::suspend_always final_suspend() noexcept {
            std::cout << "  final_suspend\n";
            return {};
        }
        void unhandled_exception() { std::terminate(); }
    };

    explicit Traced(std::coroutine_handle<promise_type> h) : h_(h) {}
    Traced(const Traced&) = delete;  // one owner for the frame
    ~Traced() {
        std::cout << "destroy\n";
        h_.destroy();
    }
    std::int64_t run() {
        h_.resume();
        return h_.promise().result;
    }

private:
    std::coroutine_handle<promise_type> h_;
};

Traced notional(std::int64_t qty, std::int64_t px_ticks) {
    std::cout << "  body: " << qty << " @ " << px_ticks << '\n';
    co_return qty * px_ticks;
}

int main() {
    std::cout << "call\n";
    Traced t = notional(100, 19275);
    std::cout << "resume\n";
    const std::int64_t value = t.run();
    std::cout << "result " << value << '\n';
}

