// -std=c++20 -fcoroutines
#include <coroutine>
#include <cstdint>
#include <exception>
#include <iostream>
#include <map>
#include <string>
#include <utility>
#include <vector>

struct Job {  // a coroutine that starts at once and runs until it waits
    struct promise_type {
        Job get_return_object() { return Job{std::coroutine_handle<promise_type>::from_promise(*this)}; }
        std::suspend_never initial_suspend() noexcept { return {}; }   // run the body right away
        std::suspend_always final_suspend() noexcept { return {}; }    // keep the frame for ~Job
        void return_void() noexcept {}
        void unhandled_exception() { std::terminate(); }
    };
    explicit Job(std::coroutine_handle<promise_type> h) : h_(h) {}
    Job(Job&& other) noexcept : h_(std::exchange(other.h_, {})) {}
    ~Job() {
        if (h_) h_.destroy();
    }
    std::coroutine_handle<promise_type> h_;
};

struct Ack {
    bool accepted;
    std::string reason;
};

class Gateway {  // parks each order's coroutine until the exchange answers
public:
    struct AckAwaiter {
        Gateway& gw;
        std::int64_t id;
        bool await_ready() const noexcept { return false; }  // an ack is never here yet
        void await_suspend(std::coroutine_handle<> h) { gw.waiting_[id] = h; }  // park it
        Ack await_resume() { return gw.acks_[id]; }  // the value of co_await
    };
    AckAwaiter ack_for(std::int64_t id) { return AckAwaiter{*this, id}; }

    void deliver(std::int64_t id, Ack ack) {  // the exchange answered: resume that order
        acks_[id] = std::move(ack);
        std::coroutine_handle<> h = waiting_[id];
        waiting_.erase(id);
        h.resume();
    }

private:
    std::map<std::int64_t, std::coroutine_handle<>> waiting_;
    std::map<std::int64_t, Ack> acks_;
};

Job place(Gateway& gw, std::int64_t id, std::int64_t qty) {
    std::cout << "order " << id << ": sent " << qty << '\n';
    const Ack ack = co_await gw.ack_for(id);  // suspends here, and resumes with the ack
    if (ack.accepted) {
        std::cout << "order " << id << ": live\n";
    } else {
        std::cout << "order " << id << ": rejected, " << ack.reason << '\n';
    }
}

int main() {
    Gateway gw;
    std::vector<Job> orders;
    orders.push_back(place(gw, 1, 100));  // each runs to its co_await, then returns here
    orders.push_back(place(gw, 2, 5000));
    orders.push_back(place(gw, 3, 300));
    std::cout << "main: all three wait\n";
    gw.deliver(2, Ack{false, "over the size limit"});  // the exchange answers out of order
    gw.deliver(3, Ack{true, ""});
    gw.deliver(1, Ack{true, ""});
}

