Task<std::int64_t> spread(std::int64_t bid, std::int64_t ask) {
    co_return ask - bid;
}

Task<std::int64_t> cost_to_cross(std::int64_t qty, std::int64_t bid, std::int64_t ask) {
    co_return qty * co_await spread(bid, ask);  // crossing pays the whole spread per share
}

Task<std::int64_t> basket_cost() {
    std::int64_t total = co_await cost_to_cross(100, 19274, 19276);
    total += co_await cost_to_cross(300, 2745, 2746);
    co_return total;
}

Task<std::int64_t> sum_spreads(std::int64_t n) {  // n awaits that each finish at once
    std::int64_t sum = 0;
    for (std::int64_t i = 1; i <= n; ++i) sum += co_await spread(i, 2 * i);
    co_return sum;
}

int main() {
    std::int64_t n = 0;
