    ~Job() { if (h_) h_.destroy(); }
    std::coroutine_handle<promise_type> h_;
};

class EventLoop {  // one thread: resumes whoever waits for each tick's symbol
public:
    struct NextTick {
        EventLoop& loop;
        std::string symbol;
        bool await_ready() const noexcept { return false; }
        void await_suspend(std::coroutine_handle<> h) { loop.waiting_[symbol].push_back(h); }
        Tick await_resume() const { return loop.current_; }
    };
    NextTick next_tick(std::string symbol) { return NextTick{*this, std::move(symbol)}; }
    void run(const std::vector<Tick>& feed) {  // a real loop would poll sockets here
        for (const Tick& t : feed) {
            current_ = t;
            const std::vector<std::coroutine_handle<>> ready = std::exchange(waiting_[t.symbol], {});
            for (std::coroutine_handle<> h : ready) h.resume();  // each runs to its next co_await
        }
    }
private:
    std::map<std::string, std::vector<std::coroutine_handle<>>> waiting_;
    Tick current_{};
};

Job average_of_three(EventLoop& loop, std::string symbol) {
    std::int64_t sum = 0;
    for (int i = 0; i < 3; ++i) sum += (co_await loop.next_tick(symbol)).px;
    std::cout << symbol << " average of 3: " << sum / 3 << '\n';
}

Job breakout(EventLoop& loop, std::string symbol, std::int64_t level) {
    for (Tick t = co_await loop.next_tick(symbol); t.px <= level; t = co_await loop.next_tick(symbol)) {
        std::cout << symbol << " at " << t.px << ", waiting for " << level << '\n';
    }
    std::cout << symbol << " broke " << level << ": buy\n";
}

